  private availability(a:ActionVm){ if(a.available===false&&a.disabledReason)return{available:false,reason:a.disabledReason}; if(a.id==="action.fighter.action-surge"&&this.sessionMode!=="initiative")return{available:false,reason:"액션 서지는 전투 중 자신의 턴에 사용합니다."}; if(this.sessionMode==="initiative"&&this.role==="player"&&a.actorId!==this.scene.currentActorId)return{available:false,reason:"현재 Actor의 턴이 아닙니다."}; const eco=this.scene.economyByActor[a.actorId]; if(this.sessionMode==="initiative"&&eco){if(a.economy==="행동"&&!eco.action&&!((a.resolutionKind==="attack"||a.id.startsWith("action.unarmed-strike."))&&eco.extraAttacks?.length)&&!eco.extraActions?.some((grant)=>a.category!=="magic"||grant.allowsMagicAction))return{available:false,reason:"행동을 이미 사용했습니다."};if(a.economy==="추가 행동"&&!eco.bonusAction)return{available:false,reason:"추가 행동을 이미 사용했습니다."};if(a.economy==="반응"&&!eco.reaction)return{available:false,reason:"반응을 이미 사용했습니다."};} if(a.resourceCost){const r=this.activeCharacter.resources.find(r=>r.id===a.resourceCost!.resourceId);if(!r||r.current<a.resourceCost.amount)return{available:false,reason:"필요 자원이 부족합니다."};} if(a.itemCost){const it=this.activeCharacter.items.find(i=>i.id===a.itemCost!.itemId);if(!it)return{available:false,reason:"필요 아이템이 없습니다."};if(a.itemCost.quantity&&(it.quantity<a.itemCost.quantity))return{available:false,reason:"아이템 수량이 부족합니다."};if(a.itemCost.charges&&(!it.charges||it.charges.current<a.itemCost.charges))return{available:false,reason:"충전이 부족합니다."};} return{available:true}; }
