  async getSnapshot():Promise<AppSnapshot>{this.syncChar();return cp({role:this.role,sessionMode:this.sessionMode,connectionState:this.connectionState,edgeState:this.edgeState,queuedD20:this.queuedD20,characters:this.characters,activeCharacter:this.activeCharacter,createDraft:this.createDraft,levelUpDraft:this.levelUpDraft,scene:this.sceneVm(),catalog:this.catalog,contentImport:this.contentImport,combatantDefinitions:this.combatantDefinitions,combatantImport:this.combatantImport,activity:this.activity,resolution:this.resolution,resolutionPresentation:this.resolutionPresentation,session:this.session});}
